#include <stdio.h>
int main(void)
{
  double a, b, r = 0;
  char op;
  int ok = 1;
  scanf("%lf %c%lf", &a, &op, &b);
  switch (op) {
    case '+': r = a + b; break;
    case '-': r = a - b; break;
    case '*': r = a * b; break;
    case '/':
      if (b == 0) ok = 0;
      else r = a / b;
      break;
    default: ok = 0;
  }
  if (ok)
    printf("%.2f\n", r);
  else
    printf("Error\n");
  return 0;
}

#include <stdio.h>
int main(void)
{
  int n;
  double fee;
  scanf("%d", &n);
  if (n <= 200)
    fee = n * 0.5;
  else if (n <= 400)
    fee = 200 * 0.5 + (n - 200) * 0.6;
  else
    fee = 200 * 0.5 + 200 * 0.6 + (n - 400) * 0.8;
  printf("%.2f\n", fee);
  return 0;
}
